var IM={hero:'https://image.qwenlm.ai/public_source/03e9d5e8-cf29-42b5-9bd3-70ee25b8df5b/1b50ec2fe-f9fc-4733-9bd3-962007d3be56.png',vessel:'https://image.qwenlm.ai/public_source/03e9d5e8-cf29-42b5-9bd3-70ee25b8df5b/1c5e653b7-cf69-4aaa-ac9f-1ff55488b002.png',ashfall:'https://image.qwenlm.ai/public_source/03e9d5e8-cf29-42b5-9bd3-70ee25b8df5b/13ff8d652-ea70-401c-b4f2-13247d8eb218.png',pale:'https://image.qwenlm.ai/public_source/03e9d5e8-cf29-42b5-9bd3-70ee25b8df5b/11f5c2ae6-b576-47f6-8777-de9d07090487.png',sungrave:'https://image.qwenlm.ai/public_source/03e9d5e8-cf29-42b5-9bd3-70ee25b8df5b/1158269a3-aab2-480b-868f-7eccfb63d5e8.png',mara:'https://image.qwenlm.ai/public_source/03e9d5e8-cf29-42b5-9bd3-70ee25b8df5b/15076c47b-b49f-4375-8b0b-c8cca8de0ba4.png',cael:'https://image.qwenlm.ai/public_source/03e9d5e8-cf29-42b5-9bd3-70ee25b8df5b/10b300052-1498-4939-8fad-928cc237a1ff.png',masked:'https://image.qwenlm.ai/public_source/03e9d5e8-cf29-42b5-9bd3-70ee25b8df5b/1440e2766-5158-4241-b1f7-d05f169c09af.png',keyart:'https://image.qwenlm.ai/public_source/03e9d5e8-cf29-42b5-9bd3-70ee25b8df5b/1532b4a7e-e165-4669-bc1a-99dac779ee2c.png',craft:'https://image.qwenlm.ai/public_source/03e9d5e8-cf29-42b5-9bd3-70ee25b8df5b/147a07667-514f-45ac-860c-ecd6f3ed0caa.png',team:'https://image.qwenlm.ai/public_source/03e9d5e8-cf29-42b5-9bd3-70ee25b8df5b/138580293-4f57-4eb3-ae4e-52d3cfa25232.png',sea:'https://image.qwenlm.ai/public_source/03e9d5e8-cf29-42b5-9bd3-70ee25b8df5b/13bd04e38-7650-4b77-bf4e-7a9cd3a10e42.png',emberwake:'https://image.qwenlm.ai/public_source/03e9d5e8-cf29-42b5-9bd3-70ee25b8df5b/189cf7b16-a933-4ac4-99b0-6773a7907cf4.png',stones:'https://image.qwenlm.ai/public_source/03e9d5e8-cf29-42b5-9bd3-70ee25b8df5b/182b9c2eb-e98d-4914-bbbf-79890ad81abe.png',choir:'https://image.qwenlm.ai/public_source/03e9d5e8-cf29-42b5-9bd3-70ee25b8df5b/135d67ed5-43d5-473e-b7f8-30a9095eb13a.png',colossus:'https://image.qwenlm.ai/public_source/03e9d5e8-cf29-42b5-9bd3-70ee25b8df5b/171020c49-7517-4840-8449-a0bdccce0e11.png'};
