/* lookups */
function byId(arr,id){for(var i=0;i<arr.length;i++)if(arr[i].id===id)return arr[i];return null}
function W(id){return byId(WORLDS,id)}function G(id){return byId(GAMES,id)}function C(id){return byId(CHARS,id)}function S(id){return byId(STORIES,id)}function A(id){return byId(ART,id)}function T(id){return byId(TEAM,id)}function J(id){return byId(JOBS,id)}function N(id){return byId(NEWS,id)}function COL(id){return byId(COLS,id)}
function routeOf(type,id){var m={world:'#/worlds/',game:'#/games/',char:'#/characters/',story:'#/stories/',art:'#/art/',news:'#/news/',team:'#/team/',job:'#/careers/',col:'#/collections/'};return (m[type]||'#/')+id}
function nameOf(type,id){var f={world:W,game:G,char:C,story:S,art:A,news:N,team:T};var o=f[type]?f[type](id):null;return o?o.title||o.name:id}
/* ================= SAVED ================= */
function getSaved(){return store.get('el_saved',[])}
function isSaved(t,id){return getSaved().some(function(x){return x[0]===t&&x[1]===id})}
function toggleSave(t,id){var s=getSaved();var i=-1;s.forEach(function(x,k){if(x[0]===t&&x[1]===id)i=k});
 if(i>-1){s.splice(i,1);toast('Removed from saved')}else{s.push([t,id]);toast('Saved to your collection')}
 store.set('el_saved',s);updateSavedUI();$$('[data-save]').forEach(function(b){var p=b.getAttribute('data-save').split(':');b.classList.toggle('saved',isSaved(p[0],p[1]));b.setAttribute('aria-pressed',isSaved(p[0],p[1]))});}
function updateSavedUI(){var n=getSaved().length;var b=$('#saved-n');b.hidden=n===0;b.textContent=n}
var toastT;function toast(m){var t=$('#toast');t.textContent=m;t.classList.add('show');clearTimeout(toastT);toastT=setTimeout(function(){t.classList.remove('show')},2200)}
/* ================= ICONS ================= */
var I_BOOK='<svg viewBox="0 0 24 24"><path d="M6 3h12v18l-6-4-6 4z"/></svg>';
/* ================= COMPONENTS ================= */
function saveBtn(t,id){return '<button class="save-btn'+(isSaved(t,id)?' saved':'')+'" data-save="'+t+':'+id+'" aria-pressed="'+isSaved(t,id)+'" aria-label="Save">'+I_BOOK+'</button>'}
function crumb(items){var h='<nav class="crumbs mono" aria-label="Breadcrumb"><a href="#/">Home</a>';items.forEach(function(c){h+='<span class="sep">/</span>'+(c[1]?'<a href="'+c[1]+'">'+c[0]+'</a>':'<span>'+c[0]+'</span>')});return h+'</nav>'}
function worldCard(w,i){return '<a class="card" href="#/worlds/'+w.id+'" data-cursor="Enter">'+saveBtn('world',w.id)+'<div class="cimg" style="aspect-ratio:4/5"><img loading="lazy" decoding="async" src="'+w.img+'" alt="'+w.alt+'"></div><div class="cmeta mono"><i>0'+((i||0)+1)+'</i><span>'+w.status+'</span></div><h3 class="ctitle">'+w.name+'</h3><p class="csub">'+w.tag+'</p></a>'}
function gameCard(g){return '<a class="card" href="#/games/'+g.id+'" data-cursor="Open">'+saveBtn('game',g.id)+'<div class="cimg" style="aspect-ratio:16/10"><img loading="lazy" decoding="async" src="'+g.img+'" alt="'+g.alt+'"></div><div class="cmeta mono"><i>'+g.status+'</i><span>'+g.release+'</span></div><h3 class="ctitle">'+g.name+'</h3><p class="csub">'+g.genre+'</p></a>'}
function storyCard(s){return '<a class="card" href="#/stories/'+s.id+'" data-cursor="Read">'+saveBtn('story',s.id)+'<div class="cimg" style="aspect-ratio:16/10"><img loading="lazy" decoding="async" src="'+s.img+'" alt="'+s.alt+'"></div><div class="cmeta mono"><i>'+s.type+'</i><span>'+fmt(s.date)+'</span><span>'+s.min+' min</span></div><h3 class="ctitle">'+s.title+'</h3><p class="csub">'+s.ex+'</p></a>'}
function charCard(c){var img=c.img?'<div class="cimg" style="aspect-ratio:4/5"><img loading="lazy" decoding="async" src="'+c.img+'" alt="'+c.alt+'"></div>':'<div class="mono-port" style="aspect-ratio:4/5"><b>'+c.name.split(' ').map(function(x){return x[0]}).join('')+'</b><span class="mono" style="color:var(--ash)">Portrait withheld — by request</span></div>';
 return '<a class="card" href="#/characters/'+c.id+'" data-cursor="Meet">'+saveBtn('char',c.id)+img+'<div class="cmeta mono"><i>'+ (c.world==='all'?'All worlds':(W(c.world)||{name:'—'}).name) +'</i></div><h3 class="ctitle">'+c.name+'</h3><p class="csub">'+c.role+' — “'+c.quote+'”</p></a>'}
function artCard(a){return '<a class="card" href="#/art/'+a.id+'" data-cursor="View">'+saveBtn('art',a.id)+'<div class="cimg" style="aspect-ratio:1/1"><img loading="lazy" decoding="async" src="'+a.img+'" alt="'+a.alt+'"></div><div class="cmeta mono"><i>'+a.kind+'</i><span>'+a.year+'</span></div><h3 class="ctitle" style="font-size:clamp(17px,1.6vw,22px)">'+a.title+'</h3></a>'}
function newsCard(n){return '<a class="card" href="#/news/'+n.id+'">'+saveBtn('news',n.id)+'<div class="cimg" style="aspect-ratio:16/9"><img loading="lazy" decoding="async" src="'+n.img+'" alt=""></div><div class="cmeta mono"><i>'+n.type+'</i><span>'+fmt(n.date)+'</span></div><h3 class="ctitle" style="font-size:clamp(18px,1.8vw,26px)">'+n.title+'</h3><p class="csub">'+n.ex+'</p></a>'}
function relStrip(title,html){if(!html)return '';return '<div class="sec warp" style="padding-top:0; max-width:var(--w);margin:0 auto;"><p class="kicker">'+title+'</p><div class="hstrip">'+html+'</div></div>'}
function empty(title,desc,cta){return '<div class="empty rv"><b>'+title+'</b><p>'+desc+'</p>'+(cta?'<a class="btn" href="'+cta[1]+'"><span class="btn-in">'+cta[0]+'</span></a>':'')+'</div>'}
function phero(kick,titleLines,lede,extra){return '<div class="dhead wrap">'+crumb(extra&&extra.crumbs||[])+ '<p class="kicker">'+kick+'</p><h1 class="pt display rv-mask" tabindex="-1">'+titleLines.map(function(l){return '<span class="ln"><span class="ln-i">'+l+'</span></span>'}).join('')+'</h1>'+(lede?'<p class="lede rv">'+lede+'</p>':'')+'</div>'}
/* ================= SEARCH INDEX ================= */
var SEARCH=[];
function pushS(type,id,title,sub,kw){SEARCH.push({type:type,id:id,title:title,sub:sub,kw:(title+' '+sub+' '+kw).toLowerCase()})}
WORLDS.forEach(function(w){pushS('world',w.id,w.name,w.tag+' · '+w.status,w.climate+' '+w.era+' locations '+w.locations.map(function(l){return l.n}).join(' '))});
GAMES.forEach(function(g){pushS('game',g.id,g.name,g.genre+' · '+g.release,g.platforms+' '+g.status)});
CHARS.forEach(function(c){pushS('character',c.id,c.name,c.role,c.quote)});
STORIES.forEach(function(s){pushS('story',s.id,s.title,s.type+' · '+fmt(s.date),s.tags.join(' '))});
ART.forEach(function(a){pushS('art',a.id,a.title,a.kind+' · '+a.year,(T(a.artist)||{name:''}).name)});
NEWS.forEach(function(n){pushS('news',n.id,n.title,n.type+' · '+fmt(n.date),'')});
TEAM.forEach(function(t){pushS('team',t.id,t.name,t.dept,t.quote)});
JOBS.forEach(function(j){pushS('job',j.id,j.title,j.dept+' · '+j.loc,'careers hiring apply')});
COLS.forEach(function(c){pushS('collection',c.id,c.title,'Collection',c.desc)});
