function homeMotion(){
 if(window.gsap&&!reduced){
  gsap.registerPlugin(ScrollTrigger);
  // Image is visible from the start — only subtle parallax/scale on scroll
  gsap.set('.hero-media',{opacity:1});
  gsap.set('#hero-gl',{opacity:0,y:40});
  var tl=gsap.timeline();
  tl.from('#h-kick',{opacity:0,y:14,duration:.7,ease:'power4.out'})
    .from(['#hl1','#hl2','#hl3'],{yPercent:112,duration:1.1,stagger:.12,ease:'power4.out'},'-=.3')
    .from('#h-cta',{opacity:0,y:20,duration:.7},'-=.5')
    .from('#h-hint',{opacity:0},'-=.4')
    .to('#hero-gl',{opacity:0.9,y:0,duration:.8,ease:'power3.out'},'-=.3');
  var st=gsap.timeline({
    scrollTrigger:{
      trigger:'#hero-wrap',
      start:'top top',
      end:'bottom bottom',
      scrub:1
    }
  });
  // Text gently lifts and fades as you scroll
  st.to(['#hl1','#hl2','#hl3'],{yPercent:-18,opacity:0,stagger:.04,duration:.4,ease:'power2.in'},0)
    .to(['#h-kick','#h-cta','#h-hint'],{opacity:0,duration:.25},0)
    // Image stays visible, only subtle scale + slight dim at the very end
    .to('.hero-media img',{scale:1.0,duration:1,ease:'none'},0)
    .to('#hero-gl',{opacity:0,y:-30,duration:.35,ease:'none'},0.55)
    .to('.hero-media',{opacity:0.35,duration:.4,ease:'none'},0.7);
  pageST.push(st);
 } else {
  var m=$('.hero-media'); if(m)m.style.opacity=1;
  var g=$('#hero-gl'); if(g)g.style.opacity=.85;
 }
}
